import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(page_title='오늘은 띄움',page_icon='🎈',layout='wide')
st.markdown('<style>.block-container{padding:0;max-width:100%}header{visibility:hidden}</style>',unsafe_allow_html=True)
components.html(r'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
*{box-sizing:border-box}body{margin:0;background:#eff9ff;color:#23364e;font-family:system-ui,'Apple SD Gothic Neo',sans-serif}button,input{font:inherit}button{cursor:pointer;border:0;border-radius:14px;padding:13px;background:#ff795f;color:#fff;font-weight:800}input{border:1px solid #cbdfea;background:#fff;color:#23364e;padding:12px;border-radius:12px;min-width:0;width:100%}main{max-width:760px;margin:auto;padding:20px}h1{margin:0;font-size:32px}p{line-height:1.6}.muted{font-size:13px;color:#547088}.card{background:#fff;border-radius:22px;padding:20px;margin:15px 0;box-shadow:0 5px 25px #3155730a}.scene{height:430px;background:linear-gradient(#91d9fc,#def5ff);border-radius:24px;position:relative;overflow:hidden}.cloud{position:absolute;background:#ffffffa8;border-radius:100%;width:160px;height:45px;top:95px;left:-20px}.cloud.two{left:auto;right:-30px;top:170px}.ground{position:absolute;bottom:0;background:#99d69b;width:100%;height:32px}.house{position:absolute;left:50%;bottom:95px;font-size:100px;transform:translateX(-50%);transition:bottom 1.5s,transform 1.5s;line-height:1;z-index:2}.house.crash{bottom:8px;transform:translateX(-50%) rotate(-18deg)}.balloon{position:absolute;width:95px;height:115px;border-radius:50% 50% 48% 48%;display:flex;align-items:center;justify-content:center;padding:10px;text-align:center;font-size:12px;font-weight:800;color:#263246;box-shadow:inset -9px -9px 0 #0000000a;transition:opacity .5s}.balloon:after{content:'';position:absolute;top:100%;left:50%;height:110px;border-left:1px solid #6c879b;transform-origin:top}.done{outline:3px solid #fff}.popped{opacity:0;pointer-events:none}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.row>*{flex:1}label{display:block;font-size:14px;margin:12px 0 6px}.task{padding:14px 0;border-bottom:1px solid #e5edf4;overflow-wrap:anywhere}.task button{font-size:13px;padding:10px}.secondary{background:#e7f1fa;color:#23364e}.warning{background:#fff0ca;border:2px solid #ffb655}.quote{font-size:21px;font-weight:900;line-height:1.7}.badge{display:inline-block;background:#fff7dd;padding:8px 12px;border-radius:20px;margin:12px 0}.hidden{display:none!important}#splash{position:fixed;inset:0;z-index:100;background:#e2f6ff;display:flex;align-items:center;justify-content:center;text-align:center}.logo{width:160px;height:160px;border-radius:38px;background:linear-gradient(145deg,#71cdf8,#ffe5a6);display:flex;align-items:center;justify-content:center;font-size:76px;margin:0 auto 20px;box-shadow:0 14px 35px #5aadc433}.small{font-size:12px}.notice{border-left:5px solid #ff795f;padding:12px;background:#fff6ec;border-radius:8px;margin:8px 0}@media(max-width:480px){main{padding:12px}.scene{height:400px}.balloon{width:78px;height:98px;font-size:11px}.house{font-size:87px}}
</style></head><body><div id="splash"><div><div class="logo">🎈🏠</div><h1>오늘은 띄움</h1><p>미루지 말고, 오늘을 띄워봐.</p></div></div><main><div class="muted">YOUR DAY, UP IN THE SKY</div><h1>오늘은 띄움 🎈</h1><p>약속을 지키면 풍선은 남고, 시간을 넘기면 터져요.</p><div class="row"><button id="playTab">🎈 내 하늘</button><button id="familyTab" class="secondary">🔔 알림함 <span id="count">0</span></button></div>
<section id="play"><div class="badge" id="status">첫 풍선을 띄워봐!</div><div class="scene"><div class="cloud"></div><div class="cloud two"></div><div id="balloons"></div><div class="house" id="house">🏠</div><div class="ground"></div></div><div id="crashCard" class="card warning hidden"><h2>💥 집이 내려앉았어!</h2><div class="quote" id="quote"></div><p>알림함에도 기록했어. 다음 도전은 행동으로 보여줘.</p><button id="another">다른 한마디</button></div><div class="card"><h2>새 할 일 풍선</h2><form id="form"><label for="title">할 일</label><input id="title" maxlength="60" placeholder="예: 수학 5문제 풀기" required><label for="deadline">완료할 날짜와 시간</label><input id="deadline" type="datetime-local" required><p class="muted">한 도전당 최대 10개. 완료한 풍선은 집을 계속 지탱해요. 모든 풍선이 기한을 넘겨 터지면 집이 무너져요.</p><button type="submit">＋ 풍선 띄우기</button></form><div id="error" role="alert"></div></div><div class="card"><h2>내 풍선들</h2><div id="tasks"></div><button id="newRound" class="secondary">새 도전 시작</button></div></section>
<section id="family" class="hidden"><div class="card"><h2>🔔 가족에게 보여줄 알림함</h2><p>이 기기의 이 브라우저에 저장되는 알림이에요. <b>가족 휴대폰으로 전송되거나 다른 기기와 공유되지는 않아요.</b></p><p class="muted">앱이 열려 있을 때 확인하며, 닫혀 있던 동안 지난 마감은 다시 열면 반영돼요. 백그라운드에서는 확인이 늦어질 수 있어요.</p><div id="notices" aria-live="polite"></div></div></section><div class="card"><b>💾 기록 보관</b><p class="muted">로그인 없이 이 브라우저에 저장해요. 시크릿 모드·브라우저 데이터 삭제·접속 주소 변경 시 기록이 사라질 수 있어요.</p><button id="backup" class="secondary">기록 백업</button><label for="restore">백업 복원 (현재 기록을 교체해요)</label><input id="restore" type="file" accept="application/json"><p id="saveState" class="muted"></p></div><p class="muted small">직접 만든 강한 동기부여 문구 500가지 조합 · 유명인 인용문이 아닙니다. 기한은 기기의 현재 시간을 기준으로 판단합니다.</p></main>
<script>
'use strict';
const $=id=>document.getElementById(id),KEY='float_today_v1';
const beginnings=['또 내일부터? 어제도 그 말 했잖아.','계획만 세울 거면 계획표는 그만 꾸며.','나중의 너한테 또 떠넘겼네.','폰 볼 시간은 있고 첫 문제 풀 시간은 없어?','말로는 이미 전교 1등이겠다.','동기부여 문구만 읽는다고 달라지진 않아.','준비만 하다가 오늘도 끝낼 거야?','미루는 실력 말고 실행력을 키워.','핑계가 한 줄 늘 때 답은 몇 줄 적었어?','네가 누른 나중에가 지금이 됐어.','책상에 앉았다고 공부가 끝난 건 아니야.','그럴듯한 목표 뒤에 숨지 마.','시작도 안 하고 어렵다는 결론부터 냈어?','계획 수정 말고 행동 수정해.','또 스크롤? 네 목표는 화면 아래에 없어.','집을 띄우는 건 다짐이 아니라 행동이야.','이럴 거면 다짐만 반복하는 건 그만해.','의욕 올 때까지 기다리다 마감이 먼저 왔네.','오늘도 미래의 너한테 빚을 남겼어.','완벽하게 못 한다고 아예 안 할 거야?','할 거라는 말은 이제 충분히 들었어.','시간이 없었다기엔 미룬 시간이 길었네.','내일의 너도 똑같이 하기 싫을 수 있어.','자료만 모으면 공부가 아니라 수집이야.','안 한 일은 저절로 사라지지 않아.'];
const endings=['지금 책 펴고 첫 줄 읽어.','폰 내려놓고 첫 문제 풀어.','2분 타이머 켜고 시작해.','가장 작은 단계 하나를 끝내.','정답 보기 전에 네 답부터 써.','노트에 내용 세 줄을 채워.','모르는 부분을 표시하고 질문해.','새 계획 말고 실행 기록을 남겨.','책상 위 방해물 하나부터 치워.','예제 하나를 네 손으로 풀어.','영상 하나 줄이고 한 페이지 넘겨.','막힌 이유를 한 줄로 적어.','지금 할 수 있는 분량으로 줄여서 해.','한 일로 증명하고 돌아와.','5분 뒤 말고 지금 시작해.','알림 끄고 한 가지에 집중해.','첫 시도가 서툴러도 일단 해.','배운 내용을 안 보고 설명해.','첫 행동을 끝내고 다음을 생각해.','이 화면 그만 보고 실제 할 일을 해.'];
const quotes=beginnings.flatMap(a=>endings.map(b=>a+' '+b));
let state={version:1,tasks:[],notices:[],crashed:false,seen:[],quote:0};
function valid(s){return s&&s.version===1&&Array.isArray(s.tasks)&&s.tasks.length<=10&&s.tasks.every(t=>typeof t.id==='string'&&typeof t.title==='string'&&t.title.length<=60&&Number.isFinite(t.due)&&['pending','done','expired'].includes(t.status))&&Array.isArray(s.notices)&&s.notices.length<=100&&s.notices.every(n=>typeof n.text==='string'&&typeof n.time==='string')&&typeof s.crashed==='boolean'&&Array.isArray(s.seen)&&s.seen.length<=500&&s.seen.every(i=>Number.isInteger(i)&&i>=0&&i<500)&&Number.isInteger(s.quote)&&s.quote>=0&&s.quote<500;}
try{const raw=localStorage.getItem(KEY);if(raw){let s=JSON.parse(raw);if(valid(s))state=s;else $('saveState').textContent='저장된 기록을 읽지 못했어요. 백업을 이용해 주세요.';}}catch(e){$('saveState').textContent='브라우저 저장소를 읽지 못했어요. 백업을 이용해 주세요.';}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('saveState').textContent='이 브라우저에 저장했어요.';}catch(e){$('saveState').textContent='자동 저장 실패! 기록 백업을 받아주세요.';}}
function nextQuote(){let left=Array.from({length:500},(_,i)=>i).filter(i=>!state.seen.includes(i));if(!left.length){state.seen=[];left=Array.from({length:500},(_,i)=>i);}state.quote=left[Math.floor(Math.random()*left.length)];state.seen.push(state.quote);}
function tick(){let changed=false;const now=Date.now();for(const t of state.tasks){if(t.status==='pending'&&now>=t.due){t.status='expired';changed=true;}}
if(state.tasks.length&&state.tasks.every(t=>t.status==='expired')&&!state.crashed){state.crashed=true;nextQuote();state.notices.unshift({time:new Date().toLocaleString('ko-KR'),text:'🎈 도전 알림: 모든 할 일 풍선이 마감을 넘겨 집이 내려앉았어요. 다음 도전을 함께 응원해 주세요.'});state.notices=state.notices.slice(0,100);changed=true;}
if(changed)save();render();}
const colors=['#ff9ca6','#ffe078','#c4b1ff','#8be0cb','#ffba7e','#9fcdff'];
function render(){const remaining=state.tasks.filter(t=>t.status!=='expired').length;const done=state.tasks.filter(t=>t.status==='done').length;
$('status').textContent=!state.tasks.length?'첫 풍선을 띄워봐!':state.crashed?'💥 집이 내려앉았어':`🎈 남은 풍선 ${remaining}개 · 완료 ${done}개`;
$('house').classList.toggle('crash',state.crashed);$('house').style.bottom=state.crashed?'8px':(55+remaining*9)+'px';$('crashCard').classList.toggle('hidden',!state.crashed);$('quote').textContent=quotes[state.quote];
$('balloons').replaceChildren();$('tasks').replaceChildren();
state.tasks.forEach((t,i)=>{const b=document.createElement('div');b.className='balloon'+(t.status==='expired'?' popped':'')+(t.status==='done'?' done':'');b.style.background=colors[i%6];b.style.left=(5+(i%5)*18)+'%';b.style.top=(22+Math.floor(i/5)*125)+'px';b.textContent=(t.status==='done'?'✓ ':'')+t.title;$('balloons').append(b);
const row=document.createElement('div');row.className='task';const title=document.createElement('b');title.textContent=t.title;row.append(title);const info=document.createElement('p');info.className='muted';let seconds=Math.max(0,Math.ceil((t.due-Date.now())/1000));info.textContent=t.status==='done'?'✅ 시간 안에 완료 · 풍선 유지':t.status==='expired'?'💥 마감 초과 · 풍선 터짐':`⏳ ${Math.floor(seconds/3600)}시간 ${Math.floor(seconds%3600/60)}분 ${seconds%60}초 남음`;row.append(info);const due=document.createElement('p');due.className='muted small';due.textContent='마감 '+new Date(t.due).toLocaleString('ko-KR');row.append(due);
if(t.status==='pending'){const btn=document.createElement('button');btn.textContent='✓ 완료했어';btn.onclick=()=>{if(Date.now()>=t.due){tick();return;}t.status='done';save();render();};row.append(btn);}$('tasks').append(row);});
if(!state.tasks.length)$('tasks').textContent='위에서 첫 할 일을 추가해봐.';$('count').textContent=state.notices.length;$('notices').replaceChildren();if(!state.notices.length)$('notices').textContent='아직 알림이 없어요.';state.notices.forEach(n=>{let div=document.createElement('div');div.className='notice';div.textContent=n.time+' · '+n.text;$('notices').append(div);});
}
$('form').onsubmit=e=>{e.preventDefault();tick();const title=$('title').value.trim(),due=new Date($('deadline').value).getTime();$('error').textContent='';if(!title||!Number.isFinite(due)||due<=Date.now()){$('error').textContent='할 일과 미래 마감 시간을 입력해줘.';return;}if(state.crashed){$('error').textContent='새 도전 시작을 눌러 다시 띄워봐.';return;}if(state.tasks.length>=10){$('error').textContent='한 도전에는 10개까지 가능해.';return;}state.tasks.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2),title,due,status:'pending'});$('title').value='';save();render();};
$('newRound').onclick=()=>{if(state.tasks.length&&!confirm('현재 풍선과 할 일을 정리하고 새 도전을 시작할까요? 알림 기록은 남아요.'))return;state.tasks=[];state.crashed=false;save();render();};
$('another').onclick=()=>{nextQuote();save();render();};$('playTab').onclick=()=>{$('play').classList.remove('hidden');$('family').classList.add('hidden');};$('familyTab').onclick=()=>{$('family').classList.remove('hidden');$('play').classList.add('hidden');};
$('backup').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='오늘은띄움_백업.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
$('restore').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1000000)throw Error('파일이 너무 커요.');const s=JSON.parse(await f.text());if(!valid(s))throw Error('올바른 백업 파일이 아니에요.');if(confirm('현재 기록을 백업으로 교체할까요?')){state=s;save();tick();}}catch(err){alert('복원 실패: '+err.message);}e.target.value='';};
let d=new Date(Date.now()+30*60000);d=new Date(d-d.getTimezoneOffset()*60000);$('deadline').value=d.toISOString().slice(0,16);tick();setInterval(tick,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});setTimeout(()=>$('splash').remove(),3000);
</script></body></html>''',height=2100,scrolling=True)
